/**
 * Geometry of the painted grammar tree (public/tree/*.webp). Generated from the artwork:
 * the bare tree was cut into a trunk and six limbs, and its twigs were traced into points.
 * Do not edit by hand.
 */

export interface TreeLimb {
  /** top-left corner and size of the limb image inside the tree painting */
  x: number;
  y: number;
  w: number;
  h: number;
  /** where the limb joins the trunk (it sways around this point) */
  px: number;
  py: number;
  /**
   * Twig points in branch order: [x, y, direction in 1/100 rad, 1 = twig tip].
   * Every tip is followed by the points on the twigs next to it.
   */
  pts: [number, number, number, number][];
}

/** Painting size in pixels; all coordinates are in this space. */
export const TREE_W = 1448;
export const TREE_H = 1086;

